1	/**
2	 * Emit the docs-only multi-theme component stylesheet to two consumers:
3	 *
4	 * - `.vitepress/theme/generated/components.css` — imported by the docs theme (`theme/index.ts`), so the
5	 *   MAIN document (and thus the inline CSS-API `@example` previews) carries every theme's component
6	 *   rules, not just rebrand.
7	 * - `public/demos-assets/components.css` — loaded by the `/play` runner iframes (see `demos.ts`'s
8	 *   `cssUrls` list).
9	 *
10	 * The shipped `@pantoken/components/components.css` is lowered to ONE theme (rebrand): `themeCustomMedia`
11	 * prunes each `@media (--theme-*)` branch at build time, so the reader's runtime theme switch (which
12	 * toggles `data-pantoken-theme`) could never bring the canvas/canvasHighContrast rules back. A rule that
13	 * changes which TOKEN a property references (e.g. billboard's `-clickable:hover` border-color:
14	 * `--instui-color-text-base` → `--instui-component-link-text-color`) can't be recovered by re-scoping
15	 * token VALUES alone. `scopedComponentsCss` emits the rebrand rules unscoped, then the other themes'
16	 * rules scoped under `:root[data-pantoken-theme="…"]` so the same attribute toggle activates them.
17	 * Mirrors how `site-themes.ts` handles token values, but for component rules. See `lib/scope-components.ts`.
18	 *
19	 * Runs in `docs:assets` (via `demos.ts`) and again on component edits during `docs:dev` (the config's
20	 * workspace orchestrator invokes this script directly). Kept as its own runnable so the watch path can
21	 * regenerate the sheet without re-staging the whole `public/` demo tree.
22	 *
23	 * @module
24	 */
25	import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
26	import { dirname, join } from "node:path";
27	import { scopedComponentsCss } from "./lib/scope-components.ts";
28	
29	const docsRoot = join(import.meta.dirname, "..");
30	
31	/** Write `theme/generated/components.css` and copy it into `public/demos-assets/`. Returns both paths. */
32	export function writeComponentsSheet(): { themeOut: string; assetsOut: string } {
33	  const themeOut = join(docsRoot, ".vitepress", "theme", "generated", "components.css");
34	  const assetsOut = join(docsRoot, "public", "demos-assets", "components.css");
35	  mkdirSync(dirname(themeOut), { recursive: true });
36	  writeFileSync(themeOut, scopedComponentsCss("instui"));
37	  // Best-effort mirror into demos-assets; on the watch path public/ already exists (docs:assets ran at
38	  // startup), and mkdirSync keeps a clean-tree run from failing.
39	  mkdirSync(dirname(assetsOut), { recursive: true });
40	  copyFileSync(themeOut, assetsOut);
41	  return { themeOut, assetsOut };
42	}
43	
44	// Run when invoked directly (`node scripts/components-sheet.ts`) — the docs:dev watch path. When
45	// imported by `demos.ts`, only the export is used.
46	if (import.meta.url === `file://${process.argv[1]}`) {
47	  writeComponentsSheet();
48	  console.log(
49	    "✓ components-sheet: wrote theme/generated/components.css + demos-assets/components.css",
50	  );
51	}
