1	/**
2	 * Stage the self-hosted demo assets into `public/` so the site can serve them:
3	 *
4	 * - the built `@pantoken/demo` runner app → `public/play/`
5	 * - the token + component stylesheets the runner injects → `public/demos-assets/`
6	 * - the committed demo snippets in `docs/demos/*.html` → `public/demos/`
7	 *
8	 * `public/` is a build artifact (gitignored), so this runs before `vitepress dev`/`build`.
9	 */
10	import {
11	  copyFileSync,
12	  cpSync,
13	  existsSync,
14	  mkdirSync,
15	  readdirSync,
16	  rmSync,
17	  writeFileSync,
18	} from "node:fs";
19	import { createRequire } from "node:module";
20	import { dirname, join } from "node:path";
21	import { writeComponentsSheet } from "./components-sheet.ts";
22	
23	const require = createRequire(import.meta.url);
24	const docsRoot = join(import.meta.dirname, "..");
25	const publicDir = join(docsRoot, "public");
26	
27	// The runner bundle uses content-hashed filenames, so a plain copy into an existing `play/` leaves the
28	// previous build's chunks behind — they pile up across rebuilds. Clear it first so only the current
29	// build's files remain. (demos-assets/ and demos/ use stable names and overwrite cleanly, so they're
30	// left as-is.)
31	const play = join(publicDir, "play");
32	rmSync(play, { recursive: true, force: true });
33	mkdirSync(play, { recursive: true });
34	const demoPkgDir = dirname(require.resolve("@pantoken/demo/package.json"));
35	const runnerDist = join(demoPkgDir, "dist/runner");
36	if (existsSync(runnerDist)) {
37	  cpSync(runnerDist, play, { recursive: true });
38	} else {
39	  console.warn(
40	    "⚠ @pantoken/demo runner is not built (run `vp run @pantoken/demo#build`); demos won't render.",
41	  );
42	}
43	
44	const assets = join(publicDir, "demos-assets");
45	mkdirSync(assets, { recursive: true });
46	
47	// The shipped components.css is lowered to ONE theme (rebrand), so its `@media (--theme-*)` overrides
48	// are pruned — the reader's runtime theme switch (which toggles `data-pantoken-theme`) could never
49	// bring them back. Emit a docs-only multi-theme sheet instead: rebrand rules unscoped, plus the
50	// canvas/canvasHighContrast overrides scoped under `:root[data-pantoken-theme="…"]` so the attribute
51	// toggle activates them. `writeComponentsSheet` writes both the theme import
52	// (theme/generated/components.css, for the MAIN document's inline `@example` previews) and this
53	// demos-assets copy (for the /play iframes), so both surfaces respond to the switch. See
54	// components-sheet.ts / lib/scope-components.ts.
55	writeComponentsSheet();
56	// Prose styles bare demo markup (headings, paragraphs, tables) with the InstUI look; it's scoped to
57	// .pantoken-prose, so it stays inert until the runner tags the result body with that class.
58	copyFileSync(require.resolve("@pantoken/components/prose.css"), join(assets, "prose.css"));
59	// The opt-in base/reset: the runner's result iframe is a pantoken-owned page, so it loads base too
60	// (page surface, box-sizing, base text) — this is also what the `base` demo showcases.
61	copyFileSync(require.resolve("@pantoken/components/base.css"), join(assets, "base.css"));
62	// The icon glyph classes (.instui-icon-<name>), so demos can render InstUI glyphs with no inline SVG.
63	copyFileSync(require.resolve("@pantoken/components/icons.css"), join(assets, "icons.css"));
64	// The experimental customizable-select enhancement (@supports base-select) — inert unless the browser
65	// supports it, so it's safe to always load; lets the simple-select demo show the styled dropdown.
66	copyFileSync(require.resolve("@pantoken/components/select.css"), join(assets, "select.css"));
67	// The cross-cutting utilities (spacing/colour classes + the View primitive), opt-in like the rest.
68	copyFileSync(require.resolve("@pantoken/components/utilities.css"), join(assets, "utilities.css"));
69	
70	// The site's multi-theme token sheet (rebrand default + canvas/canvasHighContrast scoped to
71	// `:root[data-pantoken-theme]`), generated by scripts/site-themes.ts. The runner loads this same sheet
72	// and switches theme by toggling the attribute — no per-theme sheets. site-themes.ts runs before this
73	// script (see the `docs:assets` order), so the file is fresh.
74	copyFileSync(
75	  join(docsRoot, ".vitepress/theme/generated/site-themes.css"),
76	  join(assets, "site-themes.css"),
77	);
78	
79	// `.instui-card` — the surface the /demos and the CSS-API live examples share. A static asset
80	// (tools/demo/assets/card.css); the host page imports it directly, and the runner loads the same file.
81	copyFileSync(require.resolve("@pantoken/demo/card.css"), join(assets, "card.css"));
82	
83	// The focus-outline ring and the transition/stacking/visual-debug classes are theme-independent CSS,
84	// generated once from their plugin packages (site-themes.css and @pantoken/css are built without the
85	// plugins). Both the runner (via ?css=) and the main docs site (via <head> links) load these. The named
86	// elevation shadows are NOT plugins — they ship in @pantoken/components (base.css / components.css).
87	const { toCss } = require("@pantoken/css") as typeof import("@pantoken/css");
88	const { focusOutlineCss } =
89	  require("@pantoken/components") as typeof import("@pantoken/components");
90	const { transition } =
91	  require("@pantoken/plugin-transition") as typeof import("@pantoken/plugin-transition");
92	const { stacking } =
93	  require("@pantoken/plugin-stacking") as typeof import("@pantoken/plugin-stacking");
94	const { visualDebug } =
95	  require("@pantoken/plugin-visual-debug") as typeof import("@pantoken/plugin-visual-debug");
96	writeFileSync(join(assets, "focus-outline.css"), focusOutlineCss());
97	writeFileSync(join(assets, "transition.css"), toCss([], { plugins: [transition()] }));
98	writeFileSync(join(assets, "stacking.css"), toCss([], { plugins: [stacking()] }));
99	writeFileSync(join(assets, "visual-debug.css"), toCss([], { plugins: [visualDebug()] }));
100	
101	const demosSrc = join(docsRoot, "demos");
102	const demosOut = join(publicDir, "demos");
103	mkdirSync(demosOut, { recursive: true });
104	let count = 0;
105	if (existsSync(demosSrc)) {
106	  for (const file of readdirSync(demosSrc)) {
107	    if (!file.endsWith(".html")) continue;
108	    copyFileSync(join(demosSrc, file), join(demosOut, file));
109	    count += 1;
110	  }
111	}
112	
113	console.log(
114	  `✓ staged demo runner, the shared token + plugin sheets, and ${count} demo(s) to public/`,
115	);
