1	/**
2	 * Build the docs-only multi-theme component stylesheet.
3	 *
4	 * The docs switch themes at RUNTIME by toggling `<html data-pantoken-theme="…">` (see
5	 * `.vitepress/theme/theme.ts`), while `@pantoken/components` emits CONCRETE single-theme CSS: the
6	 * `themeCustomMedia` plugin lowers each `@media (--theme-*)` branch away at build time, so the shipped
7	 * `components.css` is the rebrand variant with the canvas/canvasHighContrast rules pruned out. A theme
8	 * rule that changes which TOKEN a property references (e.g. billboard's `-clickable:hover` border-color:
9	 * `--instui-color-text-base` → `--instui-component-link-text-color`) can't be recovered by re-scoping
10	 * token VALUES alone, so those overrides never appear when the reader switches themes.
11	 *
12	 * This mirrors what `scripts/site-themes.ts` does for token values, but for component RULES: emit the
13	 * rebrand rules unscoped, then the canvas / canvasHighContrast rules scoped under
14	 * `:root[data-pantoken-theme="…"]` so the same attribute toggle activates them. Both the inline
15	 * `@example` previews and the embedded `/play` demos load this one sheet, so both respond to the switch.
16	 *
17	 * Because `themeCustomMedia` never resolves `var()`, `componentsCss({ theme })` differs from the rebrand
18	 * aggregate ONLY by the presence of theme-media-derived rules. Diffing the two at rule granularity
19	 * yields exactly the theme-only overrides — already prefix-applied, alias-correct, and in concat order.
20	 */
21	import postcss from "postcss";
22	import { componentsCss } from "@pantoken/components";
23	
24	/** The non-default themes whose overrides get attribute-scoped (rebrand is the unscoped base). */
25	const SCOPED_THEMES = ["canvas", "canvasHighContrast"] as const;
26	
27	/**
28	 * Split `input` on top-level `separator`, ignoring separators nested inside parens (so commas inside
29	 * `:is(...)` / attribute values don't split a selector list). Mirrors the plugin's helper of the same
30	 * name so selector scoping stays robust without pulling in `postcss-selector-parser`.
31	 */
32	const splitTopLevel = (input: string, separator: string): string[] => {
33	  const out: string[] = [];
34	  let depth = 0;
35	  let start = 0;
36	  for (let i = 0; i < input.length; i++) {
37	    const ch = input[i];
38	    if (ch === "(") depth++;
39	    else if (ch === ")" && depth > 0) depth--;
40	    else if (ch === separator && depth === 0) {
41	      out.push(input.slice(start, i).trim());
42	      start = i + 1;
43	    }
44	  }
45	  out.push(input.slice(start).trim());
46	  return out.filter(Boolean);
47	};
48	
49	/** Prefix every selector in a (possibly comma-separated) list with the theme's attribute compound. */
50	const scopeSelector = (selector: string, attribute: string): string =>
51	  splitTopLevel(selector, ",")
52	    .map((part) => `${attribute} ${part}`)
53	    .join(",\n");
54	
55	/**
56	 * The rebrand base sheet plus each other theme's overrides, scoped under
57	 * `:root[data-pantoken-theme="<theme>"]`. `prefix` is the class prefix (default `instui`), matching the
58	 * shipped sheet.
59	 */
60	export function scopedComponentsCss(prefix = "instui"): string {
61	  const base = componentsCss({ prefix, theme: "rebrand" });
62	
63	  // Multiset of the base sheet's top-level nodes, keyed by their serialization (which excludes the
64	  // leading whitespace `raws.before`, so it's stable across sheets). Shared rules cancel; only the
65	  // theme-media-derived extras in each themed aggregate survive the diff.
66	  const baseCounts = new Map<string, number>();
67	  for (const node of postcss.parse(base).nodes)
68	    baseCounts.set(node.toString(), (baseCounts.get(node.toString()) ?? 0) + 1);
69	
70	  const blocks: string[] = [];
71	  for (const theme of SCOPED_THEMES) {
72	    const remaining = new Map(baseCounts);
73	    const attribute = `:root[data-pantoken-theme="${theme}"]`;
74	    const deltas: string[] = [];
75	
76	    for (const node of postcss.parse(componentsCss({ prefix, theme })).nodes) {
77	      const key = node.toString();
78	      const count = remaining.get(key) ?? 0;
79	      if (count > 0) {
80	        remaining.set(key, count - 1);
81	        continue;
82	      }
83	      // A theme-only node. We only know how to attribute-scope a plain rule; a differing at-rule means
84	      // a theme `@media` lives inside an `@scope`/`@media` (or a new authoring shape we haven't handled)
85	      // — scoping it from the outside would be invalid, so fail loud rather than emit wrong CSS.
86	      if (node.type !== "rule") {
87	        throw new Error(
88	          `scope-components: theme-conditional CSS inside @scope/@media is not supported by the docs ` +
89	            `scoping mode (theme "${theme}"): ${key.slice(0, 120)}`,
90	        );
91	      }
92	      const scoped = node.clone();
93	      scoped.selector = scopeSelector(node.selector, attribute);
94	      deltas.push(scoped.toString());
95	    }
96	
97	    if (deltas.length)
98	      blocks.push(
99	        `/* ${theme} theme overrides — attribute-scoped for the docs runtime theme switch */\n` +
100	          deltas.join("\n\n"),
101	      );
102	  }
103	
104	  return `${[base.trimEnd(), ...blocks].join("\n\n")}\n`;
105	}
