1	/**
2	 * `@pantoken/components` — an InstUI-look CSS component library, built from the `--instui-*` tokens.
3	 *
4	 * The shipped stylesheets:
5	 *
6	 * - **Base** ({@link baseCss}) — opt-in global document defaults from the tokens (box-sizing, body
7	 *   reset, page surface, base text colour/font, `color-scheme`). It also carries the focus-outline
8	 *   ring, so every focusable gets an accessible `:focus-visible` outline out of the box. Load it when
9	 *   pantoken owns the page.
10	 * - **Prose** ({@link proseCss}) — styles rendered markdown/prose HTML (tables, headings, links,
11	 *   lists, code) scoped to a content root, so a docs page or content region looks like InstUI
12	 *   without swapping the DOM for components. This is what the site renderers ship as their
13	 *   `components.css`.
14	 * - **Components** ({@link buttonCss}, {@link alertCss}, {@link badgeCss}, aggregated by
15	 *   {@link componentsCss}) — class-based component styles you apply to your own markup
16	 *   (`<button class="instui-button">`), for the InstUI look outside a component framework. The
17	 *   `--instui-elevation-*` shadow scale ({@link elevationCss}) leads this sheet, since enough
18	 *   components float that shadows are an intrinsic design attribute rather than an add-on.
19	 * - **Utilities** ({@link viewCss}, {@link spacingUtilitiesCss}, {@link layoutUtilitiesCss}, plus a
20	 *   curated semantic-colour/token set) — an opt-in layer of cross-cutting classes. The generic
21	 *   token→class emitters (`colorUtilitiesCss`, `tokenUtilitiesCss`) live in `@pantoken/utils`; this
22	 *   package feeds them the curated *semantic* names, while `@pantoken/plugin-primitives` feeds the raw
23	 *   palette.
24	 * - **Fonts** (opt-in `fonts.css`) — the `@font-face` rules for the Instructure brand fonts. Base
25	 *   *applies* the font; `fonts.css` *loads* the woff2s, so text degrades gracefully without it.
26	 *
27	 * Everything is pure CSS derived from the token IR, so it tracks InstUI through the tokens with no
28	 * dependency on the InstUI React packages. For the real, interactive components, use
29	 * `@pantoken/react-markdown` (content) or `@instructure/ui-*` (apps).
30	 *
31	 * This module is a barrel: each documented record lives in its own file under
32	 * `components/`/`utilities/`/`rules/`/`declarations/`, authored with the `lib/` compose API. The
33	 * registries (`COMPONENTS`/`UTILITIES`/`RULES`/`DECLARATIONS`) drive aggregation + the parity test.
34	 *
35	 * @module
36	 * @beta
37	 */
38	import { COMPONENTS } from "./components/index.ts";
39	import { elevationCss } from "./declarations/elevation.ts";
40	import { ns, type ComponentOptions } from "./lib/helpers.ts";
41	import { base } from "./rules/base.ts";
42	import { focusOutlineCss } from "./declarations/focus.ts";
43	
44	// ── Shared options + prefix ─────────────────────────────────────────────────
45	export { DEFAULT_PREFIX, type ComponentOptions } from "./lib/helpers.ts";
46	
47	// ── Rules ───────────────────────────────────────────────────────────────────
48	export { proseCss, type ProseOptions } from "./rules/prose.ts";
49	
50	/**
51	 * Build the opt-in base/reset stylesheet: global document defaults from the tokens (box-sizing, body
52	 * reset, page surface, base text colour/font, `color-scheme`, base link), followed by the focus ring
53	 * (a document-level default that targets bare focusables). Load it once, ahead of the component and
54	 * prose sheets, when pantoken owns the page.
55	 *
56	 * @returns The CSS string.
57	 */
58	export function baseCss(): string {
59	  return `/* InstUI-look base/reset (@pantoken/components) */\n${base.rules("").trim()}\n\n${focusOutlineCss()}`;
60	}
61	
62	// ── Declarations ────────────────────────────────────────────────────────────
63	export { ELEVATION_NAMES, elevationCss, elevationDeclarations } from "./declarations/elevation.ts";
64	export {
65	  FOCUSABLE_SELECTOR,
66	  focusOutlineCss,
67	  focusOutlineDeclarations,
68	  focusOutlineRules,
69	} from "./declarations/focus.ts";
70	
71	// ── Components ──────────────────────────────────────────────────────────────
