125	// ── Utilities ───────────────────────────────────────────────────────────────
126	export { viewCss } from "./utilities/view.ts";
127	export { spacingUtilitiesCss } from "./utilities/spacing.ts";
128	export { layoutUtilitiesCss } from "./utilities/layout.ts";
129	export { responsiveUtilitiesCss } from "./utilities/responsive.ts";
130	export { iconCss } from "./utilities/icon.ts";
131	export { maskCss } from "./utilities/mask.ts";
132	export { screenReaderContentCss } from "./utilities/screen-reader-content.ts";
133	// Bespoke: the glyph-token half of the icon system (no cssdoc record).
134	export { iconGlyphsCss, type IconGlyphsOptions } from "./utilities/icon-glyphs.ts";
135	
136	/**
137	 * Build the aggregated component stylesheet: the `--instui-elevation-*` scale (so shadows are intrinsic)
138	 * followed by every component's rules in the `COMPONENTS` concat order. The size-alias and
139	 * deprecated-alias twins are appended PER COMPONENT (within its own chunk) so each alias documents on
140	 * its own page — the deprecated aliases are discovered from each record's `@deprecated {@link -x}`
141	 * metadata (see `withAliases`), not a central hand-kept list.
142	 *
143	 * @param options - {@link ComponentOptions}.
144	 * @returns The CSS string.
145	 */
146	export function componentsCss(options: ComponentOptions = {}): string {
147	  const prefix = options.prefix || "";
148	  // Each record's rules() already appends its own size/deprecated-alias twins, so this is a plain concat.
149	  const rules = COMPONENTS.map((d) => d.rules(ns(prefix), options).trim());
150	  // Elevation tokens lead the sheet so the shadows components reference (modal, alert, menu) resolve
151	  // from components.css alone — elevation is an intrinsic design attribute here, not an add-on.
