1	/**
2	 * `@pantoken/vite-workspace-orchestrator` — a Vite dev-server plugin that watches upstream workspace
3	 * packages and rebuilds them (and their dependents) when source changes.
4	 *
5	 * During development, changes to a local workspace package normally need a manual rebuild before the
6	 * dev server reflects them. This plugin automates that: it watches each upstream package's source
7	 * with native `fs.watch` (not Vite's chokidar, which filters paths outside the project root),
8	 * debounces rapid changes, rebuilds in topological order, and registers built output with Vite's
9	 * watcher so the browser reloads. In pantoken's docs it keeps the generated CSS (`@pantoken/css`,
10	 * `@pantoken/components`) fresh as you edit the libraries, instead of only at build time.
11	 *
12	 * It applies during `serve` only, so production builds are untouched.
13	 *
14	 * @example
15	 * ```ts
16	 * import { resolve } from "node:path";
17	 * import { workspaceOrchestrator } from "@pantoken/vite-workspace-orchestrator";
18	 *
19	 * workspaceOrchestrator({
20	 *   upstream: [
21	 *     {
22	 *       name: "@pantoken/components",
23	 *       dir: resolve(root, "formats/components"),
24	 *       watchPaths: [resolve(root, "formats/components/src")],
25	 *       build: ["pnpm", "run", "build"],
26	 *       dependents: [],
27	 *     },
28	 *   ],
29	 *   outputWatchPaths: [resolve(root, "formats/components/generated")],
30	 * });
31	 * ```
32	 *
33	 * @module
34	 * @experimental
35	 */
36	import { watch as watchFs } from "node:fs";
37	import type { FSWatcher } from "node:fs";
38	import { matchesGlob, resolve } from "node:path";
39	import type { ViteDevServer } from "vite";
40	import { mountFileServers } from "./file-server.ts";
41	import { createScheduler } from "./scheduler.ts";
42	import type { OrchestratorOptions, UpstreamNode } from "./types.ts";
43	
44	export type { FileServerEntry, OrchestratorOptions, UpstreamNode } from "./types.ts";
45	
46	const DEFAULT_DEBOUNCE_MS = 200;
47	
48	/**
49	 * Returns `true` if the changed filename passes the node's include/ignore filters.
50	 *
51	 * @example
52	 * ```ts
53	 * import { matchesFilters } from "@pantoken/vite-workspace-orchestrator";
54	 *
55	 * const node = {
56	 *   name: "@pantoken/components",
57	 *   dir: "/repo/formats/components",
58	 *   watchPaths: ["/repo/formats/components/src"],
59	 *   build: ["pnpm", "run", "build"] as const,
60	 *   dependents: [],
61	 *   include: ["**\/*.ts"],
62	 *   ignore: ["**\/*.test.ts"],
63	 * };
64	 *
65	 * matchesFilters("src/index.ts", node); // true
66	 * matchesFilters("src/index.test.ts", node); // false (ignored)
67	 * ```
68	 */
69	export function matchesFilters(filename: string, node: UpstreamNode): boolean {
70	  if (node.ignore?.some((pattern) => matchesGlob(filename, pattern))) return false;
71	  if (node.include && !node.include.some((pattern) => matchesGlob(filename, pattern))) return false;
72	  return true;
73	}
74	
75	/**
76	 * Create the Vite dev-server plugin.
77	 *
78	 * @param options - {@link OrchestratorOptions}.
79	 * @returns A Vite plugin object (`apply: "serve"`).
80	 */
81	export const workspaceOrchestrator = (options: OrchestratorOptions) => {
82	  const {
83	    upstream,
84	    outputWatchPaths = [],
85	    debounceMs = DEFAULT_DEBOUNCE_MS,
86	    fileServers = [],
87	  } = options;
88	
89	  return {
90	    apply: "serve" as const,
91	    name: "workspace-orchestrator",
92	    configureServer(server: ViteDevServer): void {
93	      const { logger } = server.config;
94	
95	      const nodeMap = new Map(upstream.map((n) => [n.name, n]));
96	      const scheduleRebuild = createScheduler(nodeMap, logger, debounceMs);
97	
98	      // Native fs.watch on every upstream source path. Paths that don't exist yet (pre-first-build)
99	      // are silently skipped.
100	      const fsWatchers: FSWatcher[] = [];
101	      for (const node of upstream) {
102	        for (const watchPath of node.watchPaths) {
103	          try {
104	            const watcher = watchFs(
105	              watchPath,
106	              { recursive: true },
107	              (_event: string, filename: string | null) => {
108	                if (filename !== null && !matchesFilters(filename, node)) return;
109	                scheduleRebuild(node.name);
110	              },
111	            );
112	            fsWatchers.push(watcher);
113	          } catch {
114	            // watchPath doesn't exist yet; skip silently.
115	          }
116	        }
117	      }
118	
119	      // Bridge native fs.watch notifications for each built-output path into the module graph.
120	      // chokidar's add() doesn't reliably observe pnpm-symlinked or out-of-root directories.
121	      // Emitting "change" on server.watcher lets Vite decide: CSS HMR for files in the module
122	      // graph, full page reload otherwise.
123	      for (const outputPath of outputWatchPaths) {
124	        try {
125	          const watcher = watchFs(
126	            outputPath,
127	            { recursive: true },
128	            (_event: string, filename: string | null) => {
129	              if (filename === null) return;
130	              server.watcher.emit("change", resolve(outputPath, filename));
131	            },
132	          );
133	          fsWatchers.push(watcher);
134	        } catch {
135	          // outputPath doesn't exist yet; skip silently.
136	        }
137	      }
138	
139	      mountFileServers(fileServers, server.middlewares);
140	
141	      server.httpServer?.on("close", () => {
142	        for (const w of fsWatchers) w.close();
143	      });
144	    },
145	  };
146	};
