1	/**
2	 * Types for {@link workspaceOrchestrator}.
3	 *
4	 * @module
5	 */
6	
7	/** One upstream workspace package to watch and rebuild. */
8	export interface UpstreamNode {
9	  /** Display name for log messages. */
10	  name: string;
11	  /** Package root directory (the cwd for the build command). */
12	  dir: string;
13	  /** Paths (files or directories) to watch — directories are watched recursively. */
14	  watchPaths: string[];
15	  /** Build command: first element is the executable, the rest are arguments. */
16	  build: readonly [string, ...string[]];
17	  /** Names of other upstream nodes to rebuild after this one succeeds. */
18	  dependents: readonly string[];
19	  /**
20	   * Glob patterns for files to include. When set, only changes to files matching at least one
21	   * pattern trigger a rebuild. Omit to include everything.
22	   */
23	  include?: readonly string[];
24	  /**
25	   * Glob patterns for files to ignore. Changes to matching files are silently skipped. Omit to
26	   * ignore nothing.
27	   */
28	  ignore?: readonly string[];
29	}
30	
31	/** One static file-serving middleware entry. */
32	export interface FileServerEntry {
33	  /** URL path prefix to mount the middleware at, e.g. `"/styles/apps"`. */
34	  mountPath: string;
35	  /** Local directory to serve files from. */
36	  serveDir: string;
37	  /** Only serve files whose URL path ends with this extension, e.g. `".css"`. */
38	  extension: string;
39	  /** Value for the `Content-Type` response header. */
40	  contentType: string;
41	  /**
42	   * Optional transform applied to the URL-relative path before resolving against `serveDir`, e.g.
43	   * `(p) => p.replace(/\/([^/]+)\.css$/, "/$1/app.css")`.
44	   */
45	  pathTransform?: (urlRelativePath: string) => string;
46	}
47	
48	/** Options for {@link workspaceOrchestrator}. */
49	export interface OrchestratorOptions {
50	  /** The upstream workspace dependency graph. */
51	  upstream: readonly UpstreamNode[];
52	  /**
53	   * Paths to watch with native `fs.watch` so Vite picks up built output after an upstream rebuild
54	   * (e.g. a package's `dist` or `generated` directory). Uses native `fs.watch` rather than
55	   * chokidar's `add()`, which doesn't reliably detect changes in pnpm-symlinked or out-of-root
56	   * directories. On each change a synthetic `"change"` event is emitted on `server.watcher`: for
57	   * CSS files already in the module graph Vite triggers a targeted hot-update; for anything else
58	   * it falls back to a full page reload.
59	   */
60	  outputWatchPaths?: readonly string[];
61	  /** Debounce delay in milliseconds before triggering a rebuild (default: 200). */
62	  debounceMs?: number;
63	  /** Optional static file-serving middleware entries. */
64	  fileServers?: readonly FileServerEntry[];
65	}
