14	// `:root[data-pantoken-theme="…"]`, generated by `scripts/components-sheet.ts`. The shipped sheet is
15	// lowered to one theme, so its `@media (--theme-*)` overrides are pruned; this restores them so the
16	// inline CSS-API `@example` previews re-theme on the attribute toggle. Mirrors site-themes.css above.
17	import "./generated/components.css";
18	import "@pantoken/components/utilities.css";
19	import "@pantoken/components/icons.css";
20	import "@pantoken/components/fonts.css";
21	import VitePressMermaid from "../plugins/vitepress-mermaid/index.vue";
22	import { register as registerWebComponents } from "@pantoken/web-components";
23	import "@pantoken/demo/demo.css";
24	// `.instui-card` — the shared surface for the in-page CSS-API `@example` previews (`.css-example`) and
25	// the self-hosted demos. A static asset (not generated); the runner iframe loads the same file via ?css=.
26	import "@pantoken/demo/card.css";
27	import "./pantoken.css";
28	import Layout from "./Layout.vue";
29	import { applyTheme, getStoredTheme } from "./theme";
30	
31	export default {
32	  extends: DefaultTheme,
33	  Layout,
34	  enhanceApp(ctx) {
35	    DefaultTheme.enhanceApp?.(ctx);
36	    ctx.app.component("vitepress-mermaid", VitePressMermaid);
37	
38	    // Register the pantoken custom elements so the `@example` blocks on the web-components API pages
39	    // render live (the elements inline their own CSS; the token sheet above colours them). A no-op
40	    // during SSR — it early-returns without a DOM.
41	    registerWebComponents();
42	
43	    // Wire the demo iframes: apply the persisted theme on load, then relay theme + size messages.
44	    if (typeof document !== "undefined") {
45	      // The head script already set the theme attribute (no flash); this reconciles the light/dark
46	      // class and broadcasts the theme to any demos already on the page.
47	      applyTheme(getStoredTheme());
48	
49	      // The runner (inside each figure's iframe) posts the height it wants — its toolbar plus the body
50	      // (which hugs the demo by default, capped at 30rem, or whatever height the reader dragged it to).
51	      // Match the message to its frame by source window and set the height so the iframe mirrors it.
52	      window.addEventListener("message", (event) => {
53	        const data = event.data as { type?: string; height?: number } | null;
54	        // A runner just booted and is asking which theme to render — reply to that frame only.
55	        if (data?.type === "pantoken-demo-request-theme") {
56	          (event.source as Window | null)?.postMessage(
57	            { type: "pantoken-demo-theme", theme: getStoredTheme() },
58	            "*",
59	          );
60	          return;
61	        }
62	        if (data?.type !== "pantoken-demo-size" || typeof data.height !== "number") return;
63	        const frame = [
64	          ...document.querySelectorAll<HTMLIFrameElement>(".pantoken-demo__frame"),
65	        ].find((f) => f.contentWindow === event.source);
66	        if (frame) frame.style.height = `${data.height}px`;
67	      });
68	    }
69	  },
70	} satisfies Theme;
