1	/**
2	 * A debounced, dependency-aware build scheduler for {@link workspaceOrchestrator}.
3	 *
4	 * @module
5	 */
6	import { spawn } from "node:child_process";
7	import type { UpstreamNode } from "./types.ts";
8	
9	interface BuildState {
10	  building: boolean;
11	  pending: boolean;
12	  debounce: ReturnType<typeof setTimeout> | null;
13	}
14	
15	interface Logger {
16	  info(msg: string, opts?: { timestamp?: boolean }): void;
17	  error(msg: string, opts?: { timestamp?: boolean }): void;
18	}
19	
20	const SUCCESS_EXIT_CODE = 0;
21	
22	/**
23	 * Create a debounced build scheduler for the given upstream node map. The returned function
24	 * debounces file-change events before spawning a build, re-queues a pending build if one is already
25	 * running, and rebuilds dependents in topological order on success.
26	 *
27	 * @param nodeMap - Upstream nodes keyed by name.
28	 * @param logger - The Vite logger (or any `info`/`error` sink).
29	 * @param debounceMs - Debounce delay before a build starts.
30	 * @returns A `scheduleRebuild(name)` function.
31	 */
32	export function createScheduler(
33	  nodeMap: Map<string, UpstreamNode>,
34	  logger: Logger,
35	  debounceMs: number,
36	): (name: string) => void {
37	  const stateMap = new Map<string, BuildState>(
38	    [...nodeMap.keys()].map((name) => [name, { building: false, pending: false, debounce: null }]),
39	  );
40	
41	  // The two methods are mutually recursive; co-defining them on an object avoids forward-reference
42	  // issues while keeping the closure intact.
43	  const scheduler = {
44	    scheduleRebuild(name: string): void {
45	      const s = stateMap.get(name);
46	      if (!s) return;
47	      if (s.debounce) clearTimeout(s.debounce);
48	      s.debounce = setTimeout(() => {
49	        s.debounce = null;
50	        scheduler.runBuild(name);
51	      }, debounceMs);
52	    },
53	
54	    runBuild(name: string): void {
55	      const node = nodeMap.get(name);
56	      const s = stateMap.get(name);
57	      if (!node || !s) return;
58	
59	      if (s.building) {
60	        s.pending = true;
61	        return;
62	      }
63	
64	      s.building = true;
65	      logger.info(`\n[orchestrator] ${name} — building…`, { timestamp: true });
66	
67	      const [cmd, ...args] = node.build;
68	      const child = spawn(cmd, args, { cwd: node.dir, stdio: "inherit" });
69	
70	      child.on("close", (code) => {
71	        s.building = false;
72	
73	        if (code === SUCCESS_EXIT_CODE) {
74	          logger.info(`[orchestrator] ${name} — done.`, { timestamp: true });
75	          for (const dep of node.dependents) {
76	            scheduler.scheduleRebuild(dep);
77	          }
78	        } else {
79	          logger.error(`[orchestrator] ${name} — build failed (exit ${String(code)}).`, {
80	            timestamp: true,
81	          });
82	        }
83	
84	        if (s.pending) {
85	          s.pending = false;
86	          scheduler.runBuild(name);
87	        }
88	      });
89	    },
90	  };
91	
92	  return (name) => scheduler.scheduleRebuild(name);
93	}
