11	 * attribute on `<html>` swaps the `--instui-*` set, which the `@pantoken/vitepress` bridge maps onto
12	 * `--vp-*`, re-theming the whole site. Runs in `docs:assets`, before `vitepress dev`/`build`.
13	 */
14	import { mkdirSync, writeFileSync } from "node:fs";
15	import { createRequire } from "node:module";
16	import { dirname, join } from "node:path";
17	
