20	const { byTheme, themes } = require("@pantoken/tokens") as typeof import("@pantoken/tokens");
21	
22	type ThemeKey = keyof typeof themes;
23	const DEFAULT_THEME: ThemeKey = "rebrand";
24	
25	const out = join(import.meta.dirname, "..", ".vitepress", "theme", "generated", "site-themes.css");
26	mkdirSync(dirname(out), { recursive: true });
27	
28	// The default theme: @property registrations (concrete tokens) + :root declarations (contextual).
29	const base = toCss(byTheme(DEFAULT_THEME));
30	
31	// Every other theme: only the tokens whose value differs from the default, scoped to the attribute.
32	const baseValue = new Map(byTheme(DEFAULT_THEME).map((t) => [t.name, t.value]));
33	const overrides = (Object.keys(themes) as ThemeKey[])
34	  .filter((theme) => theme !== DEFAULT_THEME)
